function persistedAssetsPage(){if(S.dataError)return head('All assets','The persisted catalog request failed; asset search is unavailable until it succeeds.','<button class="btn primary" data-action="refresh">Retry catalog request</button>')+'<section class="panel"><div class="panel-body"><div class="empty-state"><strong>Assets could not be loaded</strong><p>'+esc(S.dataError)+'</p><p>This is not an empty search result. Check the current session permissions or retry the request.</p></div></div></section>';const l=filteredCatalogAssets();return head('All assets','Search persisted assets by name, domain, owner, tags and recorded trust metadata.','<button class="btn" data-action="export-assets">Export CSV</button>')+assetCatalogOverview(l,'persisted')+'<section class="asset-catalog-controls">'+catalogFilterToolbar(l,'persisted')+'</section>'+panel('Persisted asset catalog',dynamicAssetTable(l),'Rows returned by PostgreSQL; unavailable metrics remain blank. Trust filters only use recorded metadata.')+'<div class=\"grid-equal section-spacer\">'+panel('Asset type breakdown','<div class=\"panel-body\"><div class=\"chart-wrap compact\"><canvas id=\"assetTypeChart\"></canvas></div></div>')+panel('Catalog coverage','<div class=\"panel-body\">'+assetTypeOrder().map(kind=>[kind,A.filter(a=>assetTypeCategory(a)===kind).length]).map(x=>'<div class=\"metric-line\"><span>'+esc(x[0])+'</span><strong>'+x[1]+'</strong></div>').join('')+'<p class=\"small-note\">Counts reflect the currently loaded catalog; classifications are inferred from available asset metadata.</p></div>')+'</div>';}
