let loadedDataProducts=[];
function dataProductsPage(){
  if(S.dataMode==='demo')return head('Data Products & Contracts','The persisted product registry is paused pending an access-policy review.','')+
    notice('Connected registry unavailable.','Its current API permits public writes, so this UI remains hidden in PostgreSQL mode until access is restricted.')+
    '<section class="panel"><div class="panel-body"><div class="empty-state"><strong>Registry paused</strong><p>No product records are shown in Demo mode, and the connected registry cannot be opened yet.</p></div></div></section>';
  return head('Data Products & Contracts','Discover curated data products, SLA contracts and their asset mappings.','<button class="btn primary" data-action="unavailable-data-product">+ Register Data Product</button>')+
    notice('Persisted product registry.','Product records and asset mappings are loaded from PostgreSQL. A registered product is not automatically certified or verified.')+
    '<div class="panel"><div class="panel-head"><div><h2>Registered Data Products</h2><p>Governed datasets and semantic data products.</p></div><span class="pill mint">DATABASE</span></div><div class="panel-body" id="dataProductsContainer"><div class="empty-state"><strong>Loading data products…</strong></div></div></div>';
}
async function loadDataProducts(){
  const container=$('#dataProductsContainer');if(!container||S.dataMode!=='postgresql')return;
  try{
    const res=await fetch('/api/v1/data-products',{credentials:'same-origin',headers:{Accept:'application/json'}}),json=await res.json();
    if(!res.ok||!json.ok)throw new Error(json.error||'Could not load persisted data products (HTTP '+res.status+').');
    loadedDataProducts=Array.isArray(json.data_products)?json.data_products:[];
    if(!loadedDataProducts.length){container.innerHTML='<div class="empty-state"><strong>No data products registered</strong><p>No persisted products were returned. Register one to create a real database record.</p><button class="btn primary" data-action="unavailable-data-product">+ Register Data Product</button></div>';return;}
    container.innerHTML=table(['Product Name','Domain','Owner','Status','SLA Tier','Version','Assets','Actions'],loadedDataProducts.map(p=>'<tr><td><strong>'+esc(p.name)+'</strong><div class="subline">'+esc(p.description||'')+'</div></td><td>'+esc(p.domain)+'</td><td>'+esc(p.owner)+'</td><td>'+pill(p.status)+'</td><td>'+esc(p.sla_tier||'Not recorded')+'</td><td class="mono">'+esc(p.contract_version||'Not recorded')+'</td><td class="num">'+(Array.isArray(p.asset_ids)?p.asset_ids.length:0)+'</td><td><button class="btn small" data-action="inspect-product" data-id="'+esc(p.id)+'">Inspect</button></td></tr>'));
  }catch(error){loadedDataProducts=[];container.innerHTML='<div class="empty-state"><strong>Failed to load data products</strong><p>'+esc(error.message||'Registry unavailable')+'</p><button class="btn" data-action="refresh-products">Retry</button></div>';}
}

