async function loadStewardshipQueues(){const requestsBox=$('#accessRequestsContainer'),proposalsBox=$('#glossaryProposalsContainer'),stats=$('#stewardshipStats');if(!requestsBox||!proposalsBox)return;requestsBox.innerHTML='<div class="empty-state"><strong>Loading requests…</strong></div>';proposalsBox.innerHTML='<div class="empty-state"><strong>Loading proposals…</strong></div>';try{const [rr,pr]=await Promise.all([fetch('/api/v1/requests',{credentials:'same-origin',headers:{Accept:'application/json'}}),fetch('/api/v1/proposals',{credentials:'same-origin',headers:{Accept:'application/json'}})]);const [rj,pj]=await Promise.all([rr.json(),pr.json()]);if(!rr.ok||rj.ok===false)throw new Error(rj.message||(rr.status===401||rr.status===403?'Sign in with an authorized workspace admin account to view access requests.':'Could not load persisted access requests.'));if(!pr.ok||pj.ok===false)throw new Error(pj.message||(pr.status===401||pr.status===403?'Sign in with an authorized workspace admin account to view glossary proposals.':'Could not load persisted glossary proposals.'));const reqs=rj.requests||[],props=pj.proposals||[];requestsBox.innerHTML=reqs.length?table(['Asset','Requester','Reason','Status','Action'],reqs.map(r=>'<tr><td><strong>'+esc(r.asset_name)+'</strong></td><td>'+esc(r.requester)+'</td><td>'+esc(r.reason)+'</td><td>'+pill(r.status)+'</td><td>'+(r.status==='pending'?'<button class="btn small primary" data-action="unavailable-access-decision" data-id="'+esc(r.id)+'" data-status="approved">Approve</button> <button class="btn small" data-action="unavailable-access-decision" data-id="'+esc(r.id)+'" data-status="rejected">Reject</button>':'<span class="small-note">Decision recorded</span>')+'</td></tr>')):'<div class="empty-state"><strong>No persisted access requests</strong><p>No request records were returned from PostgreSQL. No sample requests are substituted.</p></div>';proposalsBox.innerHTML=props.length?table(['Term','Definition','Proposer','Status','Action'],props.map(p=>'<tr><td><strong>'+esc(p.name)+'</strong></td><td>'+esc(p.definition)+'</td><td>'+esc(p.proposer)+'</td><td>'+pill(p.status)+'</td><td>'+(p.status==='pending'?'<button class="btn small primary" data-action="unavailable-glossary-decision" data-id="'+esc(p.id)+'" data-status="approved">Approve</button> <button class="btn small" data-action="unavailable-glossary-decision" data-id="'+esc(p.id)+'" data-status="rejected">Reject</button>':'<span class="small-note">Decision recorded</span>')+'</td></tr>')):'<div class="empty-state"><strong>No persisted glossary proposals</strong><p>No proposal records were returned from PostgreSQL. No sample terms are substituted.</p></div>';if(stats)stats.innerHTML=card('Pending Requests',String(reqs.filter(x=>x.status==='pending').length),'!','Persisted request records')+card('Approved Requests',String(reqs.filter(x=>x.status==='approved').length),'✓','Persisted decisions')+card('Glossary Proposals',String(props.length),'G','Persisted proposals')+card('Pending Proposals',String(props.filter(x=>x.status==='pending').length),'…','Awaiting review');}catch(err){const message=esc(err.message||'Governance queues could not be loaded.');requestsBox.innerHTML='<div class="empty-state"><strong>Access requests unavailable</strong><p>'+message+'</p></div>';proposalsBox.innerHTML='<div class="empty-state"><strong>Glossary proposals unavailable</strong><p>'+message+'</p></div>';if(stats)stats.innerHTML=card('Pending Requests','—','!','Unavailable')+card('Approved Requests','—','✓','Unavailable')+card('Glossary Proposals','—','G','Unavailable')+card('Pending Proposals','—','…','Unavailable');}}
